function openModal(){
  var L = story.links || {}, box = $("plinks"); box.innerHTML = "";
  $("mtitle").textContent = story.title;
  ["youtube","instagram","tiktok","facebook"].forEach(function(k){
    if (!L[k]) return;
    var a = document.createElement("a"); a.href = L[k]; a.target = "_blank"; a.rel = "noopener";
    a.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true">'+ICONS[k][1]+'</svg><span></span>→';
    a.querySelector("span").textContent = ICONS[k][0];
    box.appendChild(a);
  });
  if (!box.children.length){ var p=document.createElement("p"); p.style.margin="4px 0 8px"; p.innerHTML='The video is coming soon. Find more stories at <a href="https://'+SITE+'" target="_blank" rel="noopener" style="color:var(--navy)">'+SITE+'</a>.'; box.appendChild(p) }
  $("modal").classList.add("show"); $("mclose").focus();
}
function closeModal(){ $("modal").classList.remove("show"); $("watch").focus() }
$("watch").addEventListener("click", openModal);
$("mclose").addEventListener("click", closeModal);
$("modal").addEventListener("click", function(e){ if (e.target === this) closeModal() });
document.addEventListener("keydown", function(e){ if (e.key === "Escape" && $("modal").classList.contains("show")) closeModal() });

